mapper.select:
select temp.prd_plan_seris_id id, temp.prd_plan_seris_name text from( select distinct t.prd_plan_seris_id, t.prd_plan_seris_name from PRD_PLAN_DETAIL t where t.is_new= #{isNew}
AND ( t.prd_plan_seris_id LIKE CONCAT('%', CONCAT(#{search}, '%')) OR t.prd_plan_seris_name LIKE CONCAT('%', CONCAT(#{search}, '%')) )
union select t1.PRD_DESIGN_ID as prd_plan_seris_id, t1.PRD_DESIGN_SERIAL_NAME as prd_plan_seris_name from PRODUCT_DESIGN_INFO t1 where t1.data_status=#{dataStatus}
AND ( t1.PRD_DESIGN_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR t1.PRD_DESIGN_SERIAL_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
) temp

select EFF_DATE effDate, PRD_PLAN_SERIS_NAME prdPlanSerisName, prd_PLAN_SERIS_ID prdPlanSerisId, NON_STANDARD_LIMIT nonStandardLimit from NON_STANDARD_LIMIT_MAINT
and EFF_DATE <= to_date(#{sreachTime}, 'yyyy-MM-dd')
and PRD_PLAN_SERIS_ID=#{finPrdFamily}

select count(1) from 
NON_STANDARD_LIMIT_MAINT
where
PRD_PlAN_Seris_ID = #{prdPlanSerisId,jdbcType=VARCHAR}
and 
eff_Date=#{effDate,jdbcType=DATE}

mapper.delete:
delete from NON_STANDARD_LIMIT_MAINT
where EFF_DATE = #{effDate,jdbcType=DATE}
  and PRD_PLAN_SERIS_ID = #{prdPlanSerisId,jdbcType=VARCHAR}
